-- Candidate schema for production integration. Review before applying.
-- Do not expose service-role keys in GitHub Pages.
create table if not exists event_participants (id uuid primary key default gen_random_uuid(),event_code text not null,title text,first_name text not null,last_name text not null,email text not null,participant_role text not null,consent_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(event_code,email));
create table if not exists event_assessments (id uuid primary key default gen_random_uuid(),participant_id uuid not null references event_participants(id) on delete cascade,assessment_type text not null check (assessment_type in ('pre','post','survey')),score numeric,total numeric,response jsonb not null default '{}'::jsonb,submitted_at timestamptz not null default now(),unique(participant_id,assessment_type));
create table if not exists event_certificates (id uuid primary key default gen_random_uuid(),participant_id uuid not null unique references event_participants(id) on delete restrict,certificate_no text not null unique,approval_status text not null default 'pending' check (approval_status in ('pending','approved','revoked')),approved_by uuid,approved_at timestamptz,issued_at timestamptz,pdf_path text,verification_token uuid not null default gen_random_uuid());
-- Production requirements: enable RLS; public clients must have narrow write policies; certificate approval/issuance must be server-side/admin only; verification should return minimum fields; add retention, audit logging, rate limiting and duplicate protection.